import axios from "axios";

// frontend/src/services/api.js
const API_BASE = process.env.REACT_APP_API_URL || 'http://localhost:5000/api';

/**
 * Lấy danh sách tin tức với phân trang
 * @param {Object} params - Tham số tìm kiếm
 * @param {number} params.page - Trang hiện tại
 * @param {number} params.limit - Số bài mỗi trang
 */
export const fetchNews = async (params = {}) => {
  try {
    const { page = 1, limit = 12 } = params;
    const response = await fetch(`${API_BASE}/news?page=${page}&limit=${limit}`);
    
    if (!response.ok) {
      throw new Error(`Lỗi HTTP! status: ${response.status}`);
    }
    
    return await response.json();
  } catch (error) {
    console.error('Lỗi khi tải tin tức:', error);
    // Trả về dữ liệu mặc định nếu có lỗi
    return { articles: [], total: 0, page: 1, limit };
  }
};

/**
 * Lấy chi tiết một bài viết theo ID
 * @param {string} id - ID bài viết
 */
export const fetchArticle = async (id) => {
  try {
    const response = await fetch(`${API_BASE}/news/${id}`);
    
    if (!response.ok) {
      if (response.status === 404) {
        throw new Error('Bài viết không tồn tại');
      }
      throw new Error(`Lỗi HTTP! status: ${response.status}`);
    }
    
    const data = await response.json();
    return data.article;
  } catch (error) {
    console.error('Lỗi khi tải bài viết:', error);
    throw error; // Ném lỗi để component xử lý
  }
};
export const leadsAPI = axios.create({
  baseURL: "http://localhost:5000", // Backend port 
});

export default leadsAPI;
